<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($page['meta_title'] ?: $page['title']) ?></title><meta name="description" content="<?= e($page['meta_description']??'') ?>"><style>body{font-family:system-ui;color:#26332b;margin:0}.wrap{max-width:850px;margin:50px auto;padding:0 20px}.site-header{border-bottom:1px solid #e8ece9;padding:16px 0}.site-head{display:flex;align-items:center;justify-content:space-between;gap:18px}.site-brand{color:#176b50;font-weight:800;text-decoration:none;font-size:22px}.site-nav{display:flex;align-items:center;gap:18px;font-size:14px;font-weight:650}.site-nav a{color:#26332b;text-decoration:none;white-space:nowrap}.mobile-menu-toggle{display:none;width:42px;height:42px;border:1px solid #e5ebe6;border-radius:11px;background:#fff;color:#176b50;font-size:23px;cursor:pointer;align-items:center;justify-content:center}article{line-height:1.85;white-space:pre-line;padding:30px 0;color:#4c5a50}@media(max-width:700px){.site-head{position:relative}.mobile-menu-toggle{display:inline-flex;flex:0 0 auto}.site-nav{display:none;position:absolute;top:58px;left:0;right:0;z-index:50;padding:10px 18px 16px;background:#fff;border-bottom:1px solid #e8ece9;box-shadow:0 14px 24px #172a2018;align-items:stretch;gap:0;flex-direction:column}.site-nav.is-open{display:flex}.site-nav a{padding:13px 6px;border-bottom:1px solid #f0f2ef}.site-nav a:last-child{border-bottom:0}.wrap{margin:30px auto;padding:0 16px}}</style></head><body><header class="site-header"><div class="wrap site-head"><a class="site-brand" href="/"><?= e($siteName ?? 'VillaStay') ?></a><button class="mobile-menu-toggle" type="button" aria-label="Menüyü aç" aria-controls="siteNavigation" aria-expanded="false">☰</button><nav class="site-nav" id="siteNavigation"><?php foreach (($navigation ?? []) as $item): ?><a href="<?= e($item['url']) ?>" target="<?= e($item['target']) ?>" <?= $item['target']==='_blank'?'rel="noopener noreferrer"':'' ?>><?= e($item['label']) ?></a><?php endforeach; ?><?php if (($mode ?? 'single_vendor') === 'multi_vendor'): ?><a href="/vendor/register">Ev sahibi olun</a><?php endif; ?><?php if (($user['role'] ?? '') === 'customer'): ?><a href="/favorites">Favorilerim</a><a href="/account/bookings">Hesabım</a><?php endif; ?></nav></div></header><main class="wrap"><h1><?= e($page['title']) ?></h1><article><?= nl2br(e($page['content'])) ?></article></main><script>(function(){var button=document.querySelector(".mobile-menu-toggle"),menu=document.getElementById("siteNavigation");if(!button||!menu)return;function close(){menu.classList.remove("is-open");button.setAttribute("aria-expanded","false");button.setAttribute("aria-label","Menüyü aç");button.textContent="☰"}button.addEventListener("click",function(){var open=menu.classList.toggle("is-open");button.setAttribute("aria-expanded",open?"true":"false");button.setAttribute("aria-label",open?"Menüyü kapat":"Menüyü aç");button.textContent=open?"×":"☰"});menu.addEventListener("click",function(e){if(e.target.closest("a"))close()});document.addEventListener("keydown",function(e){if(e.key==="Escape")close()});window.addEventListener("resize",function(){if(window.innerWidth>700)close()})})();</script></body></html>